import importlib, sys

def lookup(dotted: str, attr: str):
    module = importlib.import_module(dotted)   # name -> module (cached in sys.modules)
    try:
        return getattr(module, attr)           # second-level resolution
    except AttributeError as exc:
        raise LookupError(f"{dotted} has no {attr}") from exc

importlib.invalidate_caches()                  # make finders re-resolve new modules

